#ifndef SW_OPT_RVV_OPT_H_
#define SW_OPT_RVV_OPT_H_

#include <riscv_vector.h>
#include <stddef.h>
#include <stdint.h>

namespace coralnpu_v2 {
namespace opt {

inline void* Memcpy(void* dst, const void* src, size_t n) {
  uint8_t* d = reinterpret_cast<uint8_t*>(dst);
  const uint8_t* s = reinterpret_cast<const uint8_t*>(src);
  size_t remaining = n;
  while (remaining > 0) {
    size_t vl = __riscv_vsetvl_e8m8(remaining);
    vuint8m8_t v = __riscv_vle8_v_u8m8(s, vl);
    __riscv_vse8_v_u8m8(d, v, vl);
    d += vl;
    s += vl;
    remaining -= vl;
  }
  return dst;
}

inline void* Memset(void* dst, int val, size_t n) {
  uint8_t* d = reinterpret_cast<uint8_t*>(dst);
  size_t remaining = n;
  while (remaining > 0) {
    size_t vl = __riscv_vsetvl_e8m8(remaining);
    vuint8m8_t v = __riscv_vmv_v_x_u8m8(static_cast<uint8_t>(val), vl);
    __riscv_vse8_v_u8m8(d, v, vl);
    d += vl;
    remaining -= vl;
  }
  return dst;
}

}  // namespace opt
}  // namespace coralnpu_v2

#endif  // SW_OPT_RVV_OPT_H_

