            for (int fx = 0; fx < filter_width; ++fx) {
              const int in_x = out_x * stride_width - pad_width + fx;
              if (in_x < 0 || in_x >= input_width) continue;

              const int8_t* in_ptr =
                  input_data + (batch * input_height + in_y) * input_width *
                                   input_depth +
                  in_x * input_depth + ic;
